<?php
namespace Database\Seeders; use App\Models\{Attendance,SchoolClass,SchoolSetting,Student,Teacher,User}; use App\Services\StudentBarcodeService; use Illuminate\Database\Seeder;
class DatabaseSeeder extends Seeder{public function run():void{SchoolSetting::create(['school_name'=>'Sekolah Harapan Bangsa','school_address'=>'Jl. Pendidikan No. 1, Jakarta','school_phone'=>'021-5551234','school_email'=>'info@sekolah.test','principal_name'=>'Drs. Budi Santoso','academic_year'=>'2026/2027','semester'=>'ganjil','attendance_start_time'=>'07:00','late_time_limit'=>'07:15','timezone'=>'Asia/Jakarta']);$teachers=collect(['Andi Wijaya','Siti Aminah','Rudi Hartono','Dewi Lestari','Ahmad Maulana'])->map(fn($n,$i)=>Teacher::create(['nip'=>'1980000'.($i+1),'name'=>$n,'gender'=>$i%2?'P':'L','is_active'=>true]));$classes=collect(['1A','1B','2A','2B','3A'])->map(fn($n,$i)=>SchoolClass::create(['class_name'=>$n,'grade_level'=>(int)$n[0],'teacher_id'=>$teachers[$i]->id,'academic_year'=>'2026/2027','is_active'=>true]));User::create(['name'=>'Administrator','email'=>'admin@sekolah.test','username'=>'admin','password'=>'password','role'=>'admin','is_active'=>true]);User::create(['name'=>'Kepala Sekolah','email'=>'kepala@sekolah.test','username'=>'kepala','password'=>'password','role'=>'kepala_sekolah','is_active'=>true]);foreach([0,1] as $i)User::create(['name'=>'Wali Kelas '.$classes[$i]->class_name,'email'=>'wali'.strtolower($classes[$i]->class_name).'@sekolah.test','username'=>'wali'.strtolower($classes[$i]->class_name),'password'=>'password','role'=>'wali_kelas','class_id'=>$classes[$i]->id,'is_active'=>true]);$barcode=app(StudentBarcodeService::class);$first=['Ahmad','Siti','Bima','Nabila','Rizky','Aisyah','Dimas','Putri','Fajar','Zahra'];$last=['Pratama','Saputra','Fauzan','Lestari','Ramadhan','Maharani'];for($i=1;$i<=30;$i++)Student::create(['nis'=>'2026'.str_pad((string)$i,4,'0',STR_PAD_LEFT),'nisn'=>'00'.str_pad((string)$i,8,'0',STR_PAD_LEFT),'name'=>$first[$i%10].' '.$last[$i%6],'gender'=>$i%2?'L':'P','class_id'=>$classes[($i-1)%5]->id,'barcode_token'=>$barcode->generateToken(),'is_active'=>true]);$admin=User::where('role','admin')->first();foreach(range(0,6) as $ago)foreach(Student::all() as $s){$status=['hadir','hadir','hadir','terlambat','izin','sakit','alfa'][($s->id+$ago)%7];Attendance::create(['student_id'=>$s->id,'attendance_date'=>now()->subDays($ago)->toDateString(),'check_in_time'=>in_array($status,['hadir','terlambat'])?($status==='hadir'?'07:02:00':'07:20:00'):null,'status'=>$status,'method'=>'manual','recorded_by'=>$admin->id]);}}}
